SELECT origin, username, maxOrNull(datetime) AS Last_Access FROM ${table}
WHERE datetime > NOW() - INTERVAL 30 MINUTE
AND ${generalescaping}
AND $__adHocFilter() 
AND origin != '-'
AND username != '-'
GROUP BY origin, username
ORDER BY Last_Access DESC
LIMIT ${querieslimit}
SETTINGS hdx_query_max_execution_time=60, hdx_query_admin_comment='db=${__dashboard}; dp=Last ${querieslimit} connected users; du=${__user.login}'

